\"16.3.0\",\n    \"zod\": \"^4.4.3\",\n    \"ws\": \"8.21.3\",\n    \"schemastery\": \"3.18.0\",\n    \"dsh-mnemon\": \"0.5.31\",\n    \"dsh-mnemon-source-runtime\": \"0.5.14\",\n    \"dsh-mnemon-source-documents\": \"0.5.10\",\n    \"undici\": \"6.29.1\"\n  },\n  \"dsh\": {\n    \"profile\": {\n      \"bundles\": [\n        \"@deepseek-ai/dsh-base\",\n        \"@deepseek-ai/dsh-web-app\",\n        \"dsh-web-mobile\",\n        \"dsh-better-sidebar\",\n        \"dsh-dream-skin\",\n        \"dsh-tavern-plugin\",\n        \"dsh-tavern-remote\"\n      ]\n    }\n  },\n  \"devDependencies\": {\n    \"playwright\": \"1.58.2\",\n    \"react\": \"19.2.0\",\n    \"react-dom\": \"19.2.0\",\n    \"scheduler\": \"0.27.0\",\n    \"dsh-tavern-plugin\": \"link:./tavern-plugin\",\n    \"dsh-tavern-remote\": \"link:./tavern-plugin/packages/dsh-tavern-remote\",\n    \"dsh-pocket\": \"2.12.0\",\n    \"dsh-web-mobile\": \"3.1.0\",\n    \"dsh-better-sidebar\": \"0.28.0\",\n    \"dsh-dream-skin\": \"link:./tavern-plugin/packages/dsh-dream-skin\"\n  },\n  \"description\": \"DSH Tavern: standalone tavern Profile bundle\",\n  \"engines\": {\n    \"node\": \">=22.19.0\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/flizzywine/dsh-tavern.git\"\n  }\n}\n"
